result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/pexec.py", "content": "#!/usr/bin/env python3
"""pexec.py - parallel task executor with dependency graph and output capture.

Reads a tasks.json file: [{"name": str, "cmd": str|list, "deps": [str, ...]}],
runs independent tasks concurrently (up to --jobs N) using ThreadPoolExecutor
+ subprocess, streams each task's output to .pexec/<name>.log, and prints an
event timeline (START/OK/FAIL/CANCELLED <name> at t=+x.xs).

A failure cancels not-yet-started dependents (transitively), but already
running tasks are allowed to finish.

Exit code: 0 if all non-cancelled tasks succeeded, 1 otherwise.
"""

from __future__ import annotations

import argparse
import json
import subprocess
import sys
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

T0 = time.monotonic()


def log(event: str, name: str, extra: str = "") -> None:
    t = time.monotonic() - T0
    line = f"[+{t:5.2f}s] {event:<9} {name}" + (f" {extra}" if extra else "")
    print(line, flush=True)


def validate(tasks: list[dict]) -> None:
    names = [t["name"] for t in tasks]
    if len(names) != len(set(names)):
        raise ValueError("duplicate task names")
    known = set(names)
    for t in tasks:
        for d in t.get("deps", []):
            if d not in known:
                raise ValueError(f"task {t['name']!r} depends on unknown task {d!r}")
    # cycle detection via Kahn's algorithm
    indeg = {n: 0 for n in names}
    dependents: dict[str, list[str]] = {n: [] for n in names}
    for t in tasks:
        for d in t.get("deps", []):
            indeg[t["name"]] += 1
            dependents[d].append(t["name"])
    queue = [n for n, d in indeg.items() if d == 0]
    seen = 0
    while queue:
        n = queue.pop()
        seen += 1
        for m in dependents[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                queue.append(m)
    if seen != len(names):
        raise ValueError("dependency cycle detected")


def run_task(task: dict, state: "State", log_dir: Path) -> int:
    """Run one task's command, streaming output to its log file. Returns rc."""
    cmd = task["cmd"]
    argv = cmd if isinstance(cmd, list) else ["sh", "-c", cmd]
    log_path = log_dir / f"{task['name']}.log"
    with open(log_path, "wb") as lf:
        proc = subprocess.Popen(
            argv,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            stdin=subprocess.DEVNULL,
        )
        state.register_proc(proc)
        try:
            # Stream output line-by-line into the log file as it arrives.
            assert proc.stdout is not None
            for chunk in iter(lambda: proc.stdout.read(4096), b""):
                lf.write(chunk)
                lf.flush()
        finally:
            rc = proc.wait()
    return rc


class State:
    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.failed: set[str] = set()
        self.cancelled: set[str] = set()
        self.done: set[str] = set()
        self.procs: list[subprocess.Popen] = []

    def register_proc(self, proc: subprocess.Popen) -> None:
        with self.lock:
            self.procs.append(proc)

    def mark(self, event: str, name: str) -> None:
        with self.lock:
            if event == "OK":
                self.done.add(name)
            elif event == "FAIL":
                self.failed.add(name)
                self.done.add(name)
            elif event == "CANCELLED":
                self.cancelled.add(name)
                self.done.add(name)


def ready(tasks: dict[str, dict], state: State) -> list[str]:
    """Tasks whose deps are all done successfully and which aren't done/cancelled."""
    with state.lock:
        out = []
        for name, t in tasks.items():
            if name in state.done or name in state.cancelled:
                continue
            deps = t.get("deps", [])
            if any(d in state.failed or d in state.cancelled for d in deps):
                state.cancelled.add(name)
                continue
            if all(d in state.done for d in deps):
                out.append(name)
        return out


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="parallel task executor")
    ap.add_argument("tasks_json", help="path to tasks.json")
    ap.add_argument("--jobs", type=int, default=4, help="max concurrent tasks")
    args = ap.parse_args(argv)

    raw = json.loads(Path(args.tasks_json).read_text())
    validate(raw)
    tasks = {t["name"]: t for t in raw}
    log_dir = Path(".pexec")
    log_dir.mkdir(exist_ok=True)

    state = State()
    pending = set(tasks)
    pool = ThreadPoolExecutor(max_workers=args.jobs)
    futures = {}

    try:
        while pending or futures:
            for name in ready(tasks, state):
                pending.discard(name)
                log("START", name)
                futures[
                    pool.submit(run_task, tasks[name], state, log_dir)
                ] = name
            if not futures:
                break
            # wait for at least one task to finish
            done_futs = [f for f in futures if f.done()]
            if not done_futs:
                time.sleep(0.01)
                continue
            for f in done_futs:
                name = futures.pop(f)
                rc = f.result()
                if rc == 0:
                    state.mark("OK", name)
                    log("OK", name)
                else:
                    state.mark("FAIL", name)
                    log("FAIL", name, f"(exit {rc})")
                    # transitively cancel not-yet-started dependents
                    changed = True
                    while changed:
                        changed = False
                        for n2, t2 in tasks.items():
                            if n2 in state.done or n2 in state.cancelled:
                                continue
                            if any(
                                d in state.failed or d in state.cancelled
                                for d in t2.get("deps", [])
                            ):
                                state.cancelled.add(n2)
                                pending.discard(n2)
                                changed = True
                    for c in sorted(state.cancelled):
                        pass  # logged below once, on transition
    finally:
        pool.shutdown(wait=True)

    for c in sorted(state.cancelled):
        log("CANCELLED", c)

    failed = sorted(state.failed)
    cancelled = sorted(state.cancelled)
    if failed:
        print(f"\n{len(failed)} failed: {', '.join(failed)}", file=sys.stderr)
    if cancelled:
        print(f"{len(cancelled)} cancelled: {', '.join(cancelled)}", file=sys.stderr)
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
